type Patient = { id: string; name: string; document: string; phone: string; email: string; birth: string; emergencyContact?:string; guardianName?:string; insurance?:string; alert: string; medicalHistory?:string; lastVisit: string };
type Appointment = { id: number; date: string; time: string; patientId: string; procedure: string; doctor: string; chair: string; status: string };
type StaffProfile = { userId: number; email: string; name: string; role: string; active: boolean };
type Supply = { id: number; name: string; category: string; quantity: number; minimum: number; unit: string };
type TreatmentPlan = { id: number; patientId: string; patientName?: string; title: string; status: string; totalAmount: number; createdAt?: string; items: { description: string; tooth?: string; phase?: string; amount: number; status: string }[] };
type PerioMeasurement = { patientId?:string; tooth:string;site:string;probingDepth:number;gingivalMargin:number;attachmentLevel:number;furcation:number;mobility:number;bleeding:boolean;recordedAt?:string };
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Guayaquil', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const shiftDate = (date:string,days:number) => { const value=new Date(`${date}T00:00:00Z`);value.setUTCDate(value.getUTCDate()+days);return value.toISOString().slice(0,10); };
const mondayOfWeek = (date:string) => { const day=new Date(`${date}T00:00:00Z`).getUTCDay();return shiftDate(date,-((day+6)%7)); };
type DentalData = { patients: Patient[]; appointments: Appointment[]; supplies: Supply[]; findings: Record<string, string>; notes: { patientId: string; createdAt: string; text: string }[]; plans: TreatmentPlan[]; periodontal: PerioMeasurement[] };

