function readData(): DentalData {
  try { return { ...initialData, ...JSON.parse(localStorage.getItem('sigo-dental-demo') || '{}') }; }
  catch { return initialData; }
}
const money = (n: number) => new Intl.NumberFormat('es-EC', { style: 'currency', currency: 'USD' }).format(n);
const fdi = ['18','17','16','15','14','13','12','11','21','22','23','24','25','26','27','28','48','47','46','45','44','43','42','41','31','32','33','34','35','36','37','38'];
